const { ConvexHttpClient } = require("convex/browser");
const fs = require("fs");
require("dotenv").config({ path: ".env.local" });

async function main() {
  const client = new ConvexHttpClient(process.env.CONVEX_URL);
  const tasks = await client.query("queries:getAll");
  fs.writeFileSync("/home/user/project/output.log", JSON.stringify(tasks, null, 2));
}

main().catch(console.error);

const { ConvexHttpClient } = require("convex/browser");
const fs = require("fs");

const envVars = fs.readFileSync(".env.local", "utf8").split("\n");
let convexUrl = "";
for (const line of envVars) {
  if (line.startsWith("CONVEX_URL=")) {
    convexUrl = line.split("=")[1].replace(/"/g, "").trim();
  }
}

async function main() {
  const client = new ConvexHttpClient(convexUrl);
  const tasks = await client.query("queries:getAll");
  fs.writeFileSync("/home/user/project/output.log", JSON.stringify(tasks, null, 2));
}

main().catch(console.error);

